const sourceItems = $('When Executed by Another Workflow').all();

for (const item of sourceItems) {

  const rawValue = item.json.call_ticket_object;

  let count = 0;

  try {
    const arr = typeof rawValue === 'string'
      ? JSON.parse(rawValue)
      : rawValue;

    count = Array.isArray(arr) ? arr.length : 0;

  } catch (e) {
    count = 0;
  }

  item.json.call_ticket_count = count;
}

return sourceItems;

